from functools import wraps
import six
from lxml import objectify
from taf.nms.nsp.nfmp.exception import SchemaParseError
from taf.nms.nsp.nfmp.exception import NoSuchNodeError


class BaseSchema(object):
    xml_api_version = "xmlapi_1.0"

    @staticmethod
    def _xml_as_lxml(func):
        @wraps(func)
        def wrapper(cls, xml, *args, **kwargs):
            if isinstance(xml, six.string_types):
                xml = cls.convert_to_xml_object(xml)
            return func(cls, xml, *args, **kwargs)

        return wrapper

    @staticmethod
    def convert_to_xml_object(xml_string):
        return objectify.fromstring(xml_string.encode('utf-8'))

    @classmethod
    def _extract_data(cls, xml, xml_api_version, tag_name):
        return xml.findall(".//{{{xml_api_version}}}{tag_name}".format(xml_api_version=xml_api_version,
                                                                       tag_name=tag_name))


class AlarmList(BaseSchema):
    MODULE_CLASS = 'fm.AlarmInfo'
    alarms = None

    def __init__(self, alarms):
        self.alarms = alarms

    @classmethod
    @BaseSchema._xml_as_lxml
    def from_xml(cls, xml):
        alarms = []
        for alarm_data in cls._extract_data(xml, cls.xml_api_version, cls.MODULE_CLASS):
            alarms.append(Alarm.from_xml(xml=alarm_data))

        return cls(alarms=alarms)

    def to_dict(self):
        alarm_list = []
        for alarm in self.alarms:
            alarm_list.append(alarm.to_dict())
        return alarm_list


class Alarm(BaseSchema):
    object_full_name = None
    severity = None
    alarm_name = None
    affected_object_full_name = None
    affected_object_class_name = None
    first_time_detected = None
    last_time_detected = None
    node_id = None
    node_name = None

    def __init__(self, object_full_name, severity, alarm_name, affected_object_full_name,
                 affected_object_class_name, first_time_detected, last_time_detected,
                 node_id, node_name, probable_cause, olc_state, additional_text, operator_assigned_urgency):
        self.object_full_name = object_full_name
        self.severity = severity
        self.alarm_name = alarm_name
        self.affected_object_full_name = affected_object_full_name
        self.affected_object_class_name = affected_object_class_name
        self.first_time_detected = first_time_detected
        self.last_time_detected = last_time_detected
        self.node_id = node_id
        self.node_name = node_name
        self.probable_cause = probable_cause
        self.olc_state = olc_state
        self.additional_text = additional_text
        self.operator_assigned_urgency = operator_assigned_urgency

    def to_dict(self):
        return {
            "object_full_name": self.object_full_name,
            "severity": self.severity,
            "alarm_name": self.alarm_name,
            "affected_object_full_name": self.affected_object_full_name,
            "affected_object_class_name": self.affected_object_class_name,
            "first_time_detected": self.first_time_detected,
            "last_time_detected": self.last_time_detected,
            "node_id": self.node_id,
            "node_name": self.node_name,
            "probable_cause": self.probable_cause,
            "olc_state": self.olc_state,
            "additional_text": self.additional_text,
            "operator_assigned_urgency": self.operator_assigned_urgency,
        }

    @classmethod
    @BaseSchema._xml_as_lxml
    def from_xml(cls, xml):
        return cls(
            object_full_name=xml.objectFullName,
            severity=xml.severity,
            alarm_name=xml.alarmName,
            affected_object_full_name=xml.affectedObjectFullName,
            affected_object_class_name=xml.affectedObjectClassName,
            first_time_detected=xml.firstTimeDetected,
            last_time_detected=xml.lastTimeDetected,
            node_id=xml.nodeId,
            node_name=xml.nodeName,
            probable_cause=xml.probableCause,
            olc_state=xml.olcState,
            additional_text=xml.additionalText,
            operator_assigned_urgency=xml.operatorAssignedUrgency
        )


class MrbtsInfo(BaseSchema):
    MODULE_CLASS = 'netw.NetworkElement'

    @classmethod
    @BaseSchema._xml_as_lxml
    def from_xml(cls, xml):
        network_element_data = cls._extract_data(xml, cls.xml_api_version, cls.MODULE_CLASS)[0]
        return {
            'site_id': network_element_data.siteId,
            'site_name': network_element_data.siteName,
            'displayed_name': network_element_data.displayedName,
            'sys_description': network_element_data.sysDescription,
            'ip_address': network_element_data.ipAddress,
            'location': network_element_data.location,
            'chassis_type': network_element_data.chassisType,
            'version': network_element_data.version,
            'descriptor_version': network_element_data.descriptorVersion,
            'resource_group_id': network_element_data.resourceGroupId,
            'ne_state': network_element_data.neState,
            'chassis_type_description': network_element_data.chassisTypeDescription,
            'running_sw_image': network_element_data.runningSwImage,
            'custom_property1': network_element_data.customProperty1,
            'custom_property2': network_element_data.customProperty2,
            'custom_property3': network_element_data.customProperty3,
            'flexi_model_descriptor_version': _FlexiModelDescriptorVersionClass.from_xml(network_element_data),
            'associated_peer_node_pointer': network_element_data.associatedPeerNodePointer,
            'geo_site_pointer': network_element_data.geoSitePointer,
            'activity_mode': network_element_data.activityMode,
            'redundancy_role': network_element_data.olcState,
            'lock_olc_stat': network_element_data.lockOlcState
        }


class _FlexiModelDescriptorVersionClass(BaseSchema):
    MODULE_CLASS = 'flexi.ModelDescriptorVersion'

    @classmethod
    @BaseSchema._xml_as_lxml
    def from_xml(cls, xml):
        data = []
        for item in cls._extract_data(xml, cls.xml_api_version, cls.MODULE_CLASS):
            data.append({'sub_model': item.subModel,
                         'release': item.release,
                         'adaptation_id': item.adaptationId,
                         'shelf_id': item.shelfId,
                         'site_id': item.siteId,
                         'site_name': item.siteName,
                         'displayed_name': item.displayedName,
                         'olc_state': item.olcState,
                         'lock_Olc_state': item.lockOlcState,
                         'deployment_state': item.deploymentState,
                         'object_full_name': item.objectFullName,
                         'name': item.name,
                         'self_alarmed': item.selfAlarmed})
        return data


class ResetMrbts(BaseSchema):
    DESC_TAG_NAME = 'description'

    @classmethod
    @BaseSchema._xml_as_lxml
    def from_xml(cls, xml):
        try:
            desc_data = cls._extract_data(xml, cls.xml_api_version, cls.DESC_TAG_NAME)[0]
            raise NoSuchNodeError(desc_data)
        except IndexError:
            return cls()


class NrCellInfo(BaseSchema):
    MODULE_CLASS = 'racgnb.NRCELL'
    DESC_TAG_NAME = 'description'

    @classmethod
    @BaseSchema._xml_as_lxml
    def from_xml(cls, xml):
        try:
            cell_data = cls._extract_data(xml, cls.xml_api_version, cls.MODULE_CLASS)[0]
            return {'id': cell_data.id,
                    'administrative_state': cell_data.administrativeState,
                    'availability_status': cell_data.availabilityStatus,
                    'operational_state': cell_data.operationalState,
                    'procedural_status': cell_data.proceduralStatus}
        except IndexError:
            raise NoSuchNodeError(cls._extract_data(xml, cls.xml_api_version, cls.DESC_TAG_NAME))


class HwInfo(BaseSchema):
    MODULE_CLASS = 'racgnb.HW'

    @classmethod
    @BaseSchema._xml_as_lxml
    def from_xml(cls, xml):
        hw_data = cls._extract_data(xml, cls.xml_api_version, cls.MODULE_CLASS)[0]
        return {'id': hw_data.id,
                'location_name': hw_data.locationName,
                'managed_element_type': hw_data.managedElementType,
                'sw_version': hw_data.swVersion,
                'user_label': hw_data.userLabel,
                'vendor_name': hw_data.vendorName,
                'olc_state': hw_data.olcState,
                'lock_olc_state': hw_data.lockOlcState}


class SpecificComponentSchemas(BaseSchema):
    @classmethod
    @BaseSchema._xml_as_lxml
    def from_xml(cls, xml):
        data = {}
        for index, xml_data in enumerate(cls._extract_data(xml, cls.xml_api_version, cls.MODULE_CLASS)):
            data.update(
                {xml_data.name: {'id': xml_data.id,
                                 'date_of_last_service': xml_data.dateOfLastService,
                                 'date_of_manufacture': xml_data.dateOfManufacture,
                                 'inventory_unit_type': xml_data.inventoryUnitType,
                                 'manufacturer_data': xml_data.manufacturerData,
                                 'serial_number': xml_data.serialNumber,
                                 'unit_Position': xml_data.unitPosition,
                                 'vendor_name': xml_data.vendorName,
                                 'vendor_unit_family_type': xml_data.vendorUnitFamilyType,
                                 'vendor_unit_type_number': xml_data.vendorUnitTypeNumber,
                                 'version_number': xml_data.versionNumber,
                                 'olc_state': xml_data.olcState,
                                 'lock_olc_state': xml_data.lockOlcState}
                 }
            )
        return data


