class EmptyResponse(BaseSchema):
    MODULE_CLASS = None

    @classmethod
    @BaseSchema._xml_as_lxml
    def from_xml(cls, xml):
        try:
            _ = cls._extract_data(xml, cls.xml_api_version, cls.MODULE_CLASS)[0]
            return cls()
        except (TypeError, IndexError):
            raise SchemaParseError("Could not create `{klass}` from xml='{xml}'".format(
                klass=cls.MODULE_CLASS, xml=xml))


class SetToActiveResponse(EmptyResponse):
    MODULE_CLASS = "netw.NetworkElement.setToActiveResponse"


class SetToStandbyResponse(EmptyResponse):
    MODULE_CLASS = "netw.NetworkElement.setToStandbyResponse"


class ExceptionSchema(BaseSchema):
    MODULE_CLASS = None

    def __init__(self, object_full_name, description, cause):
        self.object_full_name = object_full_name
        self.description = description
        self.cause = cause

    @classmethod
    @BaseSchema._xml_as_lxml
    def from_xml(cls, xml):
        try:
            data = cls._extract_data(xml, cls.xml_api_version, cls.MODULE_CLASS)[0]
            return cls(object_full_name=data.objectFullName,
                       description=data.description,
                       cause=getattr(data, 'cause', None))
        except (TypeError, IndexError):
            raise SchemaParseError(
                "Could not create `{klass}` from xml='{xml}'".format(
                    klass=cls.MODULE_CLASS, xml=xml))

    def to_dict(self):
        return {
            "object_full_name": self.object_full_name,
            "cause": self.cause,
            "description": self.description,
        }

    def __str__(self):
        return "\n".join(["{}: {}".format(key, value)
                          for key, value in self.to_dict().items()
                          if value is not None])


class SetToActiveException(ExceptionSchema):
    MODULE_CLASS = 'netw.NetworkElement.setToActiveException'


class SetToStandbyException(ExceptionSchema):
    MODULE_CLASS = 'netw.NetworkElement.setToStandbyException'


class UpdateFromPeerNodeResponse(EmptyResponse):
    MODULE_CLASS = 'netw.NetworkElement.updateFromPeerNodeResponse'


class UpdateFromPeerNodeException(ExceptionSchema):
    MODULE_CLASS = 'netw.NetworkElement.updateFromPeerNodeException'


